import {recordSceneAsset,alphaFor,sampleKeys,visiblePixels} from './scene-geometry.js?v=depot-v17';
import {drawBrushText,inkPaths,whiteGlyphRange} from './brush-writing.js?v=depot-v17';
import {createAtmosphere} from './atmosphere-engine.js?v=depot-v17';
const clamp=v=>Math.max(0,Math.min(1,v)),ease=v=>{v=clamp(v);return v*v*(3-2*v)};
export function noirState(age,f){const intro=f.noirFadeStart+f.noirFadeDuration+f.noirBlackHold,t=age-intro,q=ease(t/f.noirReveal),shift=ease((t-f.noirShiftStart)/f.noirShiftTime);return {intro,t,q,shift,foreground:f.noirStartScale+(f.noirEndScale-f.noirStartScale)*q,background:1+f.noirBackDepth*q,black:ease((age-f.noirFadeStart)/f.noirFadeDuration),brightness:clamp(q*1.2)*f.noirExposure/100}}
// Anchored text uses the same world transform as the cutout for every reveal frame.
export function noirTextPose(layer,s,f,pose={x:0,y:0,scale:1,rotation:0}){const depth=layer.depth||0;if(layer.anchor!=='people')return {x:layer.x+s.shift*f.noirShift*depth,y:layer.y-s.shift*35*depth,scale:1+depth*s.q*.12,rotation:layer.rotation||0};const reference=.82,dx=(layer.x-480)/reference,dy=(layer.y-152)/reference,angle=pose.rotation*Math.PI/180,k=s.foreground*pose.scale;return {x:480+s.shift*f.noirShift+pose.x+(Math.cos(angle)*dx-Math.sin(angle)*dy)*k,y:60+s.q*92+s.shift*8+pose.y+(Math.sin(angle)*dx+Math.cos(angle)*dy)*k,scale:(1+depth*.12)*k/reference,rotation:(layer.rotation||0)+pose.rotation}}
export function createNoirScene(){const atmosphere=createAtmosphere(),textCache=new Map(),buffers={};for(const k of ['men','head','text','white']){const c=document.createElement('canvas');c.width=960;c.height=540;buffers[k]=c}function cover(ctx,im){if(!im?.naturalWidth)return;const scale=Math.max(960/im.naturalWidth,540/im.naturalHeight);ctx.drawImage(im,480-im.naturalWidth*scale/2,270-im.naturalHeight*scale/2,im.naturalWidth*scale,im.naturalHeight*scale)}
return function render(ctx,age,fx,sprites){ctx.canvas.sceneAssets=[];const s=noirState(age,fx);if(!fx.noirTransparent){ctx.fillStyle='#000';ctx.fillRect(0,0,960,540)}if(s.t<0)return;if(!fx.noirTransparent){ctx.save();ctx.translate(480-s.shift*40,270);ctx.scale(s.background,s.background);ctx.translate(-480,-270);cover(ctx,sprites.mysterySky);ctx.restore();atmosphere.paint(ctx,s.t,fx.noirClouds);recordSceneAsset(ctx,{id:'noir-clouds',kind:'flow',name:'Sky clouds',flowKey:'noirClouds'},[0,0,960,300])}
const men=buffers.men,m=men.getContext('2d'),head=buffers.head,hc=head.getContext('2d');m.clearRect(0,0,960,540);hc.clearRect(0,0,960,540);const pose=sampleKeys({x:fx.noirMenX||0,y:fx.noirMenY||0,scale:fx.noirMenScale??1,rotation:fx.noirMenRotation||0},s.t,fx.noirMenKeys||[]);if(sprites.mysteryMen?.naturalWidth){m.save();m.translate(480+s.shift*fx.noirShift+pose.x,60+s.q*92+s.shift*8+pose.y);m.rotate(pose.rotation*Math.PI/180);m.scale(s.foreground*pose.scale,s.foreground*pose.scale);m.translate(-480,-60);const im=sprites.mysteryMen,h=520,w=h*im.naturalWidth/im.naturalHeight;m.filter=`brightness(${.4+.6*s.q})`;m.drawImage(im,480-w/2,20,w,h);const matrix=m.getTransform();if(matrix&&Number.isFinite(matrix.a)){hc.setTransform(matrix);hc.filter=m.filter;hc.drawImage(im,im.naturalWidth*.60,0,im.naturalWidth*.19,im.naturalHeight*.16,480-w/2+w*.60,20,w*.19,h*.16);hc.setTransform(1,0,0,1,0,0);hc.filter='none';ctx.save();ctx.setTransform(matrix);recordSceneAsset(ctx,{id:'noir-men',name:'People cutout',kind:'men',assetSlot:'mysteryMen'},[480-w/2,20,w,h],alphaFor(im));ctx.restore()}m.restore()}for(const layer of fx.noirTexts)if(layer.visible!==false&&layer.order==='behind')textLayer(ctx,layer,layer.color);ctx.drawImage(men,0,0);if(sprites.soil?.naturalWidth){ctx.save();ctx.beginPath();ctx.moveTo(0,540);for(let x=0;x<=960;x+=8)ctx.lineTo(x,525+Math.sin(x*.023)*7+Math.sin(x*.071)*3);ctx.lineTo(960,540);ctx.closePath();ctx.clip();ctx.filter='grayscale(.8) brightness(.45)';ctx.drawImage(sprites.soil,0,505,960,140);ctx.restore()}
function textLayer(target,layer,color,glyphProgress=null){const timing=fx.noirTextSync===false?1:fx.noirReveal/10,p=ease((s.t-layer.start*timing)/Math.max(.1,layer.duration*timing));if(p<=0)return;const progress=Math.round(p*120)/120,cacheId=layer.id+'|'+color,key=[layer.text,layer.size,progress,layer.style].join('|');let cached=textCache.get(cacheId);const pad=layer.size*.6;if(!cached||cached.key!==key){const canvas=cached?.canvas||document.createElement('canvas');canvas.width=Math.min(8192,Math.ceil(inkPaths(layer.text,layer.size).width+pad*2));canvas.height=Math.ceil(layer.size*2.8);const c=canvas.getContext('2d');c.translate(pad,pad);c.strokeStyle=color;drawBrushText(c,layer.text,layer.size,progress,layer.style);canvas._alphaVersion=key;cached={key,canvas};if(textCache.size>32)textCache.clear();textCache.set(cacheId,cached)}target.save();const placement=noirTextPose(layer,s,fx,pose);target.translate(placement.x,placement.y);target.scale(placement.scale,placement.scale);target.rotate(placement.rotation*Math.PI/180);if(layer.order!=='behind'&&layer.id==='secrets'){target.shadowColor='#eee8da';target.shadowBlur=2.5}if(glyphProgress!==null){target.beginPath();for(const b of whiteGlyphRange(layer.text,layer.size,layer.whiteGlyphStart??3,layer.whiteGlyphEnd??6,glyphProgress))target.rect(b.x,b.y,b.width,b.height);target.clip()}target.filter=`blur(${layer.blur||0}px)`;target.drawImage(cached.canvas,-pad,-pad);if(target===ctx){const pixels=visiblePixels(cached.canvas);if(pixels){const [x,y,w,h]=pixels.rect;recordSceneAsset(target,{id:'text:'+layer.id,kind:'text',name:layer.text,layerId:layer.id},[x-pad,y-pad,w,h],pixels.alpha)}}target.restore()}
for(const layer of fx.noirTexts){if(layer.visible===false||layer.order==='behind')continue;textLayer(ctx,layer,layer.color);if(layer.order==='under-head'){ctx.save();ctx.drawImage(layer.anchor==='people'?men:head,0,0);ctx.restore()}if(layer.frontContrast&&layer.order!=='behind'){const contrast=buffers.text,cc=contrast.getContext('2d');cc.clearRect(0,0,960,540);textLayer(cc,layer,layer.whiteColor||'#fff5ff');cc.save();cc.globalCompositeOperation='destination-in';cc.drawImage(men,0,0);cc.restore();ctx.drawImage(contrast,0,0)}if(layer.whiteStart!=null&&layer.whiteMode!=='none'){const timing=fx.noirTextSync===false?1:fx.noirReveal/10,white=ease((s.t-layer.whiteStart*timing)/Math.max(.1,(layer.whiteDuration||3)*timing));if(white>0){const c=buffers.white,w=c.getContext('2d');w.clearRect(0,0,960,540);textLayer(w,layer,layer.whiteColor||'#fff',layer.whiteMode==='glyph-spread'?white:null);w.save();w.globalCompositeOperation='destination-in';if(layer.whiteMode==='silhouette')w.drawImage(men,0,0);else if(layer.whiteMode==='wipe'){w.fillStyle='white';w.fillRect(0,0,960*white,540)}w.restore();ctx.save();ctx.globalAlpha=white;ctx.drawImage(c,0,0);ctx.restore()}}}
if(fx.noirTransparent)return;ctx.fillStyle='#000';ctx.globalAlpha=1-Math.min(1,s.brightness);ctx.fillRect(0,0,960,540);ctx.globalAlpha=1;const vignette=ctx.createRadialGradient(480,240,170,480,240,680);vignette.addColorStop(0,'transparent');vignette.addColorStop(1,'#0007');ctx.fillStyle=vignette;ctx.fillRect(0,0,960,540)}
}
